mapper.select:
SELECT game_id, skill_key, effect_key, name, description, sort_order, created_at, updated_at
FROM public.skill_effects
WHERE game_id = #{gameId} AND skill_key = #{skillKey} AND effect_key = #{effectKey}

SELECT COUNT(1)
FROM public.skill_effects
WHERE game_id = #{gameId} AND skill_key = #{skillKey} AND effect_key = #{effectKey}

mapper.insert:
INSERT INTO public.skill_effects (
    game_id, skill_key, effect_key, name, description, sort_order
) VALUES (
    #{gameId}, #{skillKey}, #{effectKey}, #{name}, #{description}, #{sortOrder}
)

INSERT INTO public.skill_effect_results (
    game_id, skill_key, effect_key, result_key, name, result_type, target, description, sort_order
) VALUES (
    #{gameId}, #{skillKey}, #{effectKey}, #{resultKey}, #{name},
    #{resultType}, #{target}, #{description}, #{sortOrder}
)

mapper.update:
UPDATE public.skill_effect_results
SET name = #{name},
    target = #{target},
    description = #{description},
    sort_order = #{sortOrder}
WHERE game_id = #{gameId}
  AND skill_key = #{skillKey}
  AND effect_key = #{effectKey}
  AND result_key = #{resultKey}

mapper.delete:
DELETE FROM public.skill_effect_results
WHERE game_id = #{gameId}
  AND skill_key = #{skillKey}
  AND effect_key = #{effectKey}
  AND result_key IN

    #{resultKey}

