SELECT t.game_id, t.skill_key, t.effect_key, t.result_key, t.affected_skill_key
FROM public.skill_effect_cooldown_change_targets t
JOIN public.skills s
  ON s.game_id = t.game_id
 AND s.skill_key = t.affected_skill_key
WHERE t.game_id = #{gameId}
  AND t.skill_key = #{skillKey}
  AND t.effect_key = #{effectKey}
ORDER BY s.sort_order, t.affected_skill_key

